from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak
from reportlab.lib.enums import TA_CENTER
from pathlib import Path

root = Path(__file__).parent
out = root / 'FINAL_PROJECT_REPORT.pdf'
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle', parent=styles['Title'], alignment=TA_CENTER, fontSize=20, leading=26, textColor=colors.HexColor('#174A6E'), spaceAfter=14))
styles.add(ParagraphStyle(name='SmallNote', parent=styles['BodyText'], fontSize=8, leading=11, textColor=colors.HexColor('#555555')))
story=[]
story += [Spacer(1,2*cm), Paragraph('FINAL PROJECT REPORT', styles['CoverTitle']), Paragraph('Enterprise Workflow Automation &amp; Intelligent Document Processing System', styles['Heading2']), Spacer(1,0.7*cm)]
meta=[['Project ID','PY-W4-004'],['Domain','Python Development'],['Project level','Advanced / Industry-oriented'],['Technology','Python, FastAPI, SQLAlchemy, SQLite, Streamlit'],['Submission organization','AB Infotech Solutions Pvt. Ltd. (ABIS)']]
t=Table(meta,colWidths=[5*cm,11*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(0,-1),colors.HexColor('#EAF2F8')),('GRID',(0,0),(-1,-1),0.5,colors.HexColor('#AAB7B8')),('FONTNAME',(0,0),(0,-1),'Helvetica-Bold'),('PADDING',(0,0),(-1,-1),8)])); story += [t,Spacer(1,1.2*cm),Paragraph('Prepared as a technical summary of the included educational application.',styles['BodyText']),PageBreak()]
story += [Paragraph('1. Project Overview',styles['Heading1']),Paragraph('The project is a local-first Python application that demonstrates centralized employee and department records, document intake and extraction, approval workflow tracking, REST APIs, authentication, reporting, and an administrative dashboard.',styles['BodyText']),Spacer(1,8)]
story += [Paragraph('2. Implemented Modules',styles['Heading1'])]
modules=[['Module','Included implementation'],['Application / API','FastAPI application with Swagger/OpenAPI documentation and modular route handlers.'],['Database','SQLAlchemy ORM with SQLite; schema reference and backup helper.'],['Employee & Department','CRUD endpoints, validation, duplicate checks, and department association.'],['Document Processing','PDF, CSV, TXT, DOCX support; metadata, SHA-256 duplicate detection, text extraction and keyword classification.'],['Workflow','Pending-to-approved/rejected transitions, activity history and overdue query.'],['Security','Password hashing, JWT bearer authentication and role checks.'],['Reporting','JSON summary, CSV employee export, PDF summary and scheduled report script.'],['Dashboard','Streamlit overview with API authentication and downloadable CSV.'],['Testing','Pytest starter tests for API, database, document utilities and workflow transitions.']]
t=Table(modules,colWidths=[4*cm,12*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#174A6E')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('GRID',(0,0),(-1,-1),0.35,colors.HexColor('#BFC9CA')),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),6)])); story += [t,Spacer(1,10)]
story += [Paragraph('3. Architecture',styles['Heading1']),Paragraph('Users interact with the FastAPI service through Swagger/API clients or the Streamlit dashboard. API routes apply authentication and role checks, then use SQLAlchemy to access SQLite. Document files are stored under uploads/, while application and workflow events are logged.',styles['BodyText']),Spacer(1,8),Image(str(root/'documentation/architecture_diagram.png'),width=16*cm,height=9*cm),PageBreak()]
story += [Paragraph('4. Database Design',styles['Heading1']),Paragraph('The relational schema contains users, departments, employees, documents, workflows, and workflow_activities. Foreign keys connect employees to departments, documents and workflows to users, workflows to optional documents, and activities to workflows. See database/schema.sql and the ER diagram.',styles['BodyText']),Spacer(1,8),Image(str(root/'documentation/database_erd.png'),width=16*cm,height=8*cm),Spacer(1,12)]
story += [Paragraph('5. Run and Verify',styles['Heading1']),Paragraph('Install dependencies from requirements.txt, create .env from .env.example, run `python run.py`, then open `http://127.0.0.1:8000/docs`. Run the dashboard in a second terminal with `streamlit run dashboard/admin_dashboard.py`. Run automated tests with `pytest -q` after dependencies are installed.',styles['BodyText']),Spacer(1,8)]
story += [Paragraph('6. Scope Notes and Limitations',styles['Heading1']),Paragraph('This is an educational reference implementation, not a production-hardened enterprise deployment. Notifications are logged locally; optional SMTP delivery requires configuration. The dashboard is a read-only overview. The first account registered in a fresh local database becomes admin for demo bootstrap. Production deployment should add controlled administrator provisioning, database migrations, rate limiting, malware scanning and stronger file signature validation, managed secrets, automated scheduling/backup operations, and broader integration/load testing.',styles['BodyText']),Spacer(1,8)]
story += [Paragraph('7. Evidence and Final Submission',styles['Heading1']),Paragraph('The documentation/screenshots folder lists the real application screenshots to capture: health API, authentication, employee API, document upload, workflow decision/history, reports, dashboard, and test results. Add screenshots from the actual local run before emailing. Include the GitHub repository URL only after creating and verifying the repository.',styles['BodyText']),Spacer(1,12),Paragraph('Project ID: PY-W4-004 | Final technical summary',styles['SmallNote'])]
doc=SimpleDocTemplate(str(out),pagesize=A4,rightMargin=1.7*cm,leftMargin=1.7*cm,topMargin=1.5*cm,bottomMargin=1.5*cm,title='PY-W4-004 Final Project Report')
doc.build(story)
print(out)
